// 1.9.9.2.1 — Accetta solo immagini raster incorporate, mai URL o SVG importati.
// Le immagini create dal programma sono JPEG; PNG/WebP/GIF sono consentiti per vecchi archivi.
const SAFE_IMAGE_RE=/^data:image\/(?:jpeg|png|webp|gif);base64,(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/i;
function safeImageData(value){return typeof value==='string'&&value.length<=20*1024*1024&&SAFE_IMAGE_RE.test(value)}
function imgSrc(value){return safeImageData(value)?esc(value):''}
function validateImportedContent(root){
 let seen=new WeakSet(), nodes=0;
 function walk(value,path,depth){
  if(depth>40||++nodes>200000)throw Error('Archivio troppo complesso');
  if(value===null||typeof value==='string'||typeof value==='number'||typeof value==='boolean')return;
  if(typeof value!=='object')throw Error('Tipo di dato non valido in '+path);
  if(seen.has(value))throw Error('Riferimento circolare in '+path);
  seen.add(value);
  if(Array.isArray(value)){for(let i=0;i<value.length;i++)walk(value[i],path+'['+i+']',depth+1);return}
  for(const [key,v] of Object.entries(value)){
   if(['__proto__','prototype','constructor'].includes(key))throw Error('Proprietà non ammessa nel backup');
   if(key==='fotoEdificio'&&v!==null&&v!==''&&!safeImageData(v))throw Error('Fotografia edificio non valida');
   if(key==='foto'){
    if(!Array.isArray(v))throw Error('Elenco fotografie non valido');
    for(const f of v){if(!f||typeof f!=='object'||Array.isArray(f)||typeof f.name!=='string'||f.name.length>500||!safeImageData(f.data))throw Error('Fotografia non valida nel backup');}
   }
   if(key==='data'&&typeof v==='string'&&v.startsWith('data:')&&!safeImageData(v))throw Error('Contenuto incorporato non sicuro');
   walk(v,path+'.'+key,depth+1);
  }
 }
 walk(root,'backup',0);
}

// 1.9.9.4: distingue la presenza fisica di cancelli/porte/sbarre dallo stato manutentivo.
// Dati legacy: la presenza resta "Non verificata" fino alla conferma del tecnico.
const EQUIPMENT_PRESENCE=[["","Non verificato"],["presente","Presente"],["non-presente","Non presente"],["na","Non applicabile"]];
function techInput(t,d){
 let x=d||{};
 let one=(name,opts)=>select(name,t.key+(name==="Manutenzione periodica"?"Manutenzione":name==="Verifica periodica"?"Verifica":""),opts,x[name==="Manutenzione periodica"?"manutenzione":name==="Verifica periodica"?"verifica":"valore"]||"");
 let inner;
 if(t.presence){
  const present=x.presenza==="presente";
  inner=select("Presenza dell'impianto",t.key+"Presenza",EQUIPMENT_PRESENCE,x.presenza||"")+
   `<div class="tech-presence-dependent" ${present?'':'hidden'}><div class="formgrid">${one("Manutenzione periodica",YES_NO_NA)}${one("Verifica periodica",YES_NO_NA)}</div></div>`+
   `<small class="tech-presence-hint">Seleziona «Presente» per indicare manutenzione e verifiche. «Non presente» indica che l'impianto non esiste, non una manutenzione omessa.</small>`;
 }else if(t.double)inner=one("Manutenzione periodica",YES_NO_NA)+one("Verifica periodica",YES_NO_NA);
 else if(t.number)inner=field("Numero di persone",t.key+"Valore",x.valore||"","number",'min="0" step="1"');
 else inner=one("Stato",t.opts);
 return `<div class="tech-item" data-tech="${t.key}"><div class="tech-head"><b>${esc(t.label)}</b></div><div class="formgrid">${inner}</div><div class="field"><label>Note tecniche</label><textarea class="tech-note" placeholder="Osservazioni relative a questo punto">${esc(x.note||"")}</textarea></div><div class="field"><label>Fotografie allegate</label><input class="tech-upload" type="file" accept="image/*" multiple><div class="tech-photos photo">${(x.foto||[]).map((f,i)=>`<div><img src="${imgSrc(f.data)}" alt="Foto"><small>${esc(f.name||"Foto")}</small><button type="button" class="secondary tech-remove" data-index="${i}">Rimuovi</button></div>`).join("")}</div></div></div>`;
}
function techRead(t,d){
 let x=d||{}, vals;
 if(t.presence){
  let presenza=x.presenza||"";
  if(presenza==="presente")vals=`<b>Presenza:</b> Presente · Manutenzione periodica: ${esc(fmt(x.manutenzione))} · Verifica periodica: ${esc(fmt(x.verifica))}`;
  else if(presenza==="non-presente")vals=`<b>Presenza:</b> Non presente (manutenzione e verifiche non applicabili)`;
  else if(presenza==="na")vals=`<b>Presenza:</b> Non applicabile`;
  else vals=`<b>Presenza:</b> Non verificata${(x.manutenzione||x.verifica)?' · Dati manutentivi precedenti da riconfermare nella scheda anagrafica':''}`;
 }else if(t.double)vals=`Manutenzione periodica: ${esc(fmt(x.manutenzione))} · Verifica periodica: ${esc(fmt(x.verifica))}`;
 else if(['chiaviSblocco','dispositiviAntincendio','cartellonistica','luciEmergenza'].includes(t.key))vals=esc(x.valore?fmt(x.valore):'Non verificato');
 else vals=esc(fmt(x.valore));
 return `<div class="report-tech"><b>${esc(t.label)}</b><div>${vals}</div>${x.note?`<div>Note: ${esc(x.note)}</div>`:""}${(x.foto||[]).length?`<div class="report-photos">${x.foto.map(f=>`<figure><img src="${imgSrc(f.data)}" alt="Foto allegata"><figcaption>${esc(f.name||"Fotografia")}</figcaption></figure>`).join("")}</div>`:""}</div>`;
}
