function compress(file){return new Promise((ok,no)=>{let im=new Image(),u=URL.createObjectURL(file);im.onload=()=>{let s=Math.min(1,1400/Math.max(im.width,im.height)),canvas=document.createElement("canvas");canvas.width=Math.round(im.width*s);canvas.height=Math.round(im.height*s);canvas.getContext("2d").drawImage(im,0,0,canvas.width,canvas.height);URL.revokeObjectURL(u);ok(canvas.toDataURL("image/jpeg",.75))};im.onerror=()=>{URL.revokeObjectURL(u);no(Error("Immagine non valida"))};im.src=u})}
